import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { Eye, EyeOff, LogOut, User, Home, ShoppingCart } from 'lucide-react';

function App() {
  const [medicines, setMedicines] = useState([]);
  const [searchTerm, setSearchTerm] = useState("");
  const [view, setView] = useState("home"); // "home" or "profile"
  const [cart, setCart] = useState([]); // Stores items for the profile

  // --- Login & UI States ---
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [showPassword, setShowPassword] = useState(false);
  const [loginData, setLoginData] = useState({ email: '', password: '' });

  useEffect(() => {
    if (isLoggedIn) {
      fetchMedicines();
    }
  }, [isLoggedIn]);

  const fetchMedicines = async () => {
    try {
      const response = await axios.get('http://localhost:8080/api/medicines');
      setMedicines(response.data);
    } catch (error) {
      console.error("Error fetching medicines", error);
    }
  };

  const handleAddToCart = async (med) => {
    if (med.stock <= 0) {
      alert("Out of Stock!");
      return;
    }
    try {
      await axios.put(`http://localhost:8080/api/medicines/reduce/${med.id}/1`);

      // Update local Cart state for the Profile Page
      setCart((prevCart) => {
        const existingItem = prevCart.find(item => item.id === med.id);
        if (existingItem) {
          return prevCart.map(item =>
            item.id === med.id ? { ...item, quantity: item.quantity + 1 } : item
          );
        }
        return [...prevCart, { ...med, quantity: 1 }];
      });

      alert(`Added ${med.name} to cart!`);
      fetchMedicines();
    } catch (error) {
      alert("Error updating stock.");
    }
  };

  const filteredMedicines = medicines.filter(med =>
    med.name.toLowerCase().includes(searchTerm.toLowerCase())
  );

  // --- COMPONENT: PROFILE PAGE ---
  const ProfilePage = () => (
    <div style={{ padding: '40px' }}>
      <h1>👤 User Profile</h1>
      <div style={{ padding: '20px', border: '1px solid #ddd', borderRadius: '8px', backgroundColor: '#f9f9f9', marginBottom: '20px' }}>
        <p><strong>Email:</strong> {loginData.email}</p>
        <p><strong>Status:</strong> Active Customer</p>
      </div>

      <h2>🛒 Your Cart Items</h2>
      <table border="1" style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'center' }}>
        <thead>
          <tr style={{ backgroundColor: '#eee' }}>
            <th style={{ padding: '10px' }}>Medicine</th>
            <th style={{ padding: '10px' }}>Price</th>
            <th style={{ padding: '10px' }}>Quantity</th>
            <th style={{ padding: '10px' }}>Total</th>
          </tr>
        </thead>
        <tbody>
          {cart.map((item, index) => (
            <tr key={index}>
              <td style={{ padding: '10px' }}>{item.name}</td>
              <td style={{ padding: '10px' }}>${item.price}</td>
              <td style={{ padding: '10px' }}>{item.quantity}</td>
              <td style={{ padding: '10px' }}>${(item.price * item.quantity).toFixed(2)}</td>
            </tr>
          ))}
        </tbody>
      </table>
      {cart.length === 0 && <p style={{ textAlign: 'center', marginTop: '10px' }}>Your cart is empty.</p>}
      <h3 style={{ textAlign: 'right', marginTop: '20px' }}>
        Grand Total: ${cart.reduce((acc, item) => acc + (item.price * item.quantity), 0).toFixed(2)}
      </h3>
    </div>
  );

  // --- CONDITION: SHOW LOGIN IF NOT LOGGED IN ---
  if (!isLoggedIn) {
    return (
      <div style={{ maxWidth: '400px', margin: '100px auto', padding: '30px', border: '1px solid #ddd', borderRadius: '10px', textAlign: 'center', boxShadow: '0px 4px 10px rgba(0,0,0,0.1)' }}>
        <h2>💊 Medi-Hub Login</h2>
        <input
          type="email"
          placeholder="Email Address"
          style={{ width: '100%', padding: '10px', marginBottom: '15px', borderRadius: '5px', border: '1px solid #ccc' }}
          onChange={(e) => setLoginData({ ...loginData, email: e.target.value })}
        />
        <div style={{ position: 'relative', marginBottom: '20px' }}>
          <input
            type={showPassword ? "text" : "password"}
            placeholder="Password"
            style={{ width: '100%', padding: '10px', borderRadius: '5px', border: '1px solid #ccc' }}
            onChange={(e) => setLoginData({ ...loginData, password: e.target.value })}
          />
          <span onClick={() => setShowPassword(!showPassword)} style={{ position: 'absolute', right: '10px', top: '10px', cursor: 'pointer', color: '#666' }}>
            {showPassword ? <EyeOff size={20} /> : <Eye size={20} />}
          </span>
        </div>
        <button onClick={() => setIsLoggedIn(true)} style={{ width: '100%', padding: '10px', backgroundColor: '#007bff', color: 'white', border: 'none', borderRadius: '5px', cursor: 'pointer', fontWeight: 'bold' }}>
          Login
        </button>
      </div>
    );
  }
  // // Add this inside function App() 
  // const medicineImages = {
  //   "Napa": "https://example.com/napa-tablet.jpg",
  //   "Ace": "https://example.com/ace-pills.jpg",
  //   "Seclo": "https://example.com/seclo-capsule.jpg",
  //   "Fexo": "https://example.com/fexo-120.jpg",
  //   // Fallback image if a name isn't found in this list
  //   "default": "https://images.unsplash.com/photo-1584308666744-24d5c474f2ae?w=400"
  // };

  const medicineImages = {
    "Paracetamol": "data:image/jpeg;base64,",
    "Pan-D": "data:image/jpeg;base64,",
    "Mondeslor": "data:image/jpeg;base64,",
    "AB Phylline SR 200": "data:image/jpeg;base64,",
    "Amoxicillin": "data:image/jpeg;base64,",
    "Ibuprofen": "data:image/jpeg;base64,",
    "Cetirizine": "data:image/jpeg;base64,",
    "Metformin": "data:image/jpeg;base64,",
    "Atorvastatin": "data:image/jpeg;base64,",
    "default": "https://images.unsplash.com/photo-1584308666744-24d5c474f2ae?w=400"
  };

  // --- FINAL RETURN: NAVBAR + SWITCHABLE CONTENT ---
  return (
    <div style={{ minHeight: '100vh', backgroundColor: '#f8f9fa', fontFamily: 'sans-serif' }}>
      {/* 1. Navbar (Always Visible) */}
      <nav style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '10px 40px', backgroundColor: '#007bff', color: 'white', position: 'sticky', top: 0, zIndex: 1000 }}>
        <h2 onClick={() => setView("home")} style={{ cursor: 'pointer', margin: 0 }}>🏥 Medi-Hub</h2>
        <div style={{ display: 'flex', gap: '25px', alignItems: 'center' }}>
          <Home onClick={() => setView("home")} style={{ cursor: 'pointer' }} size={24} />
          <div onClick={() => setView("profile")} style={{ cursor: 'pointer', display: 'flex', alignItems: 'center', gap: '5px' }}>
            <User size={24} />
            <span style={{ fontWeight: 'bold' }}>Profile</span>
          </div>
          <LogOut onClick={() => setIsLoggedIn(false)} style={{ cursor: 'pointer' }} size={24} />
        </div>
      </nav>

      {/* 2. Switch between Home (Cards) and Profile */}
      {view === "home" ? (
        <div style={{ padding: '40px' }}>
          <div style={{ textAlign: 'center', marginBottom: '40px' }}>
            <h1 style={{ color: '#333' }}>Available Medicines</h1>
            <input
              type="text"
              placeholder="🔍 Search for medicine by name..."
              style={{ width: '60%', padding: '15px 25px', fontSize: '16px', borderRadius: '30px', border: '1px solid #ddd', outline: 'none', boxShadow: '0 4px 6px rgba(0,0,0,0.05)' }}
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>

          {/* MEDICINE CARDS GRID */}
          <div style={{
            display: 'grid',
            gridTemplateColumns: 'repeat(auto-fill, minmax(280px, 1fr))',
            gap: '30px',
            maxWidth: '1200px',
            margin: '0 auto',
          }}>
            {filteredMedicines.map((med) => (
              <div key={med.id} style={{
                backgroundColor: 'white',
                borderRadius: '15px',
                overflow: 'hidden',
                boxShadow: '0 10px 20px rgba(0,0,0,0.05)',
                display: 'flex',
                flexDirection: 'column',
                border: '1px solid #eee',
                /* Inside your card div style */
                transition: 'transform 0.2s, boxShadow 0.2s',
                cursor: 'pointer',
                // Note: To make hover truly work in inline styles, you'd usually use a CSS file, 
                // but for now, the transition makes the 'transform' we added earlier look smooth!
              }}>
                {/* Image Section */}
                <div style={{ height: '200px', backgroundColor: '#eee', overflow: 'hidden' }}>
                  <img
                    /* Looks up the URL by the medicine's name. If not found, uses the default. */
                    src={medicineImages[med.name] || medicineImages["default"]}
                    alt={med.name}
                    style={{ width: '100%', height: '100%', objectFit: 'cover' }}
                    onError={(e) => { e.target.src = medicineImages["default"]; }}
                  />
                </div>

                {/* Content Section */}
                <div style={{ padding: '20px', flex: 1, display: 'flex', flexDirection: 'column' }}>
                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
                    <h3 style={{ margin: '0', fontSize: '20px', color: '#333' }}>{med.name}</h3>
                    <span style={{ fontSize: '12px', background: '#e7f3ff', color: '#007bff', padding: '4px 10px', borderRadius: '20px', fontWeight: 'bold' }}>
                      {med.category}
                    </span>
                  </div>

                  <div style={{ margin: '15px 0', fontSize: '24px', fontWeight: 'bold', color: '#28a745' }}>
                    ${med.price.toFixed(2)}
                  </div>

                  <div style={{ marginBottom: '20px' }}>
                    {med.stock > 0 ? (
                      <span style={{ color: '#28a745', fontSize: '14px', fontWeight: 'bold' }}>● In Stock ({med.stock})</span>
                    ) : (
                      <span style={{ color: '#dc3545', fontSize: '14px', fontWeight: 'bold' }}>● Out of Stock</span>
                    )}
                  </div>

                  <button
                    onClick={() => handleAddToCart(med)}
                    disabled={med.stock <= 0}
                    style={{
                      marginTop: 'auto',
                      backgroundColor: med.stock > 0 ? '#ffc107' : '#ddd',
                      cursor: med.stock > 0 ? 'pointer' : 'not-allowed',
                      border: 'none',
                      padding: '12px',
                      borderRadius: '8px',
                      fontWeight: 'bold',
                      fontSize: '16px',
                      display: 'flex',
                      alignItems: 'center',
                      justifyContent: 'center',
                      gap: '10px'
                    }}
                  >
                    <ShoppingCart size={20} />
                    {med.stock > 0 ? "Add to Cart" : "Out of Stock"}
                  </button>
                </div>
              </div>
            ))}
          </div>

          {filteredMedicines.length === 0 && (
            <p style={{ textAlign: 'center', marginTop: '50px', fontSize: '18px', color: '#666' }}>No medicines found.</p>
          )}
        </div>
      ) : (
        <ProfilePage />
      )}
    </div>
  );
}

export default App;